import{_ as n,C as s,o as a,c as o,a2 as i,b as c,w as t,a as l,E as d,a3 as h}from"./chunks/framework.XaTYfhfj.js";const v=JSON.parse('{"title":"14.6 Multi-Tier Caching & Invalidation Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.6-caching.md","filePath":"system-design/14.6-caching.md"}'),u={name:"system-design/14.6-caching.md"};function g(m,e,p,T,C,_){const r=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=i('<h1 id="_14-6-multi-tier-caching-invalidation-architecture" tabindex="-1">14.6 Multi-Tier Caching &amp; Invalidation Architecture <a class="header-anchor" href="#_14-6-multi-tier-caching-invalidation-architecture" aria-label="Permalink to &quot;14.6 Multi-Tier Caching &amp; Invalidation Architecture&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Caching is the strategy of storing frequently accessed data in high-speed, temporary storage layers (such as RAM or edge servers) to serve subsequent requests faster and reduce load on primary databases and expensive AI compute models.</p><hr><h2 id="_2-truthguard-multi-tier-caching-topology" tabindex="-1">2. TruthGuard Multi-Tier Caching Topology <a class="header-anchor" href="#_2-truthguard-multi-tier-caching-topology" aria-label="Permalink to &quot;2. TruthGuard Multi-Tier Caching Topology&quot;">​</a></h2>',5)),(a(),c(h,null,{default:t(()=>[d(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20User(%5BForensic%20Analyst%5D)%20--%3E%20Tier1%5BTier%201%3A%20Browser%20Memory%20%2F%20TanStack%20Query%20Cache%5D%0A%20%20%20%20Tier1%20--%3E%7CCache%20Miss%7C%20Tier2%5BTier%202%3A%20Global%20Cloudflare%20CDN%20Edge%20Cache%5D%0A%20%20%20%20Tier2%20--%3E%7CCache%20Miss%7C%20Tier3%5BTier%203%3A%20Redis%20Semantic%20Hash%20Cache%20(Key%3A%20SHA-256)%5D%0A%20%20%20%20Tier3%20--%3E%7CCache%20Miss%7C%20Tier4%5BTier%204%3A%20Serverless%20AI%20Inference%20%26%20PostgreSQL%5D%0A%0A%20%20%20%20Tier4%20--%3E%7CStore%20Result%7C%20Tier3%0A%20%20%20%20Tier3%20--%3E%7CCache-Aside%20Response%7C%20User%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<hr><h2 id="_3-caching-tiers-evaluated" tabindex="-1">3. Caching Tiers Evaluated <a class="header-anchor" href="#_3-caching-tiers-evaluated" aria-label="Permalink to &quot;3. Caching Tiers Evaluated&quot;">​</a></h2><ol><li><strong>Tier 1 (Client-Side Query Cache)</strong>: Managed via <code>@tanstack/react-query</code> in [<code>App.tsx</code>](file:///Users/avishjain/avishjain9-repos/33-codealchemist/mainpage/src/App.tsx#L12-L15). Prevents duplicate API requests during component re-mounts using a 5-minute stale-time window.</li><li><strong>Tier 2 (CDN Edge Cache)</strong>: Caches static JavaScript, CSS bundles, and VitePress documentation files with immutable cache-control headers (<code>Cache-Control: public, max-age=31536000, immutable</code>).</li><li><strong>Tier 3 (Semantic Redis Cache by SHA-256)</strong>: <ul><li>When an analyst submits an image or video, the client calculates its 64-character SHA-256 hash.</li><li>The edge gateway checks Redis: <code>GET forensic:hash:&lt;sha256&gt;</code>.</li><li>If a match exists, the cached verdict and confidence score return in &lt;5 milliseconds, completely bypassing costly AI inference.</li><li><strong>Strategy</strong>: Cache-Aside (Lazy Loading) with a 30-day Time-To-Live (TTL).</li></ul></li></ol><hr><h2 id="_4-cache-invalidation-stampede-protection" tabindex="-1">4. Cache Invalidation &amp; Stampede Protection <a class="header-anchor" href="#_4-cache-invalidation-stampede-protection" aria-label="Permalink to &quot;4. Cache Invalidation &amp; Stampede Protection&quot;">​</a></h2><ul><li><strong>Cache Stampede / Thundering Herd Prevention</strong>: If a breaking deepfake video goes viral and 10,000 analysts submit it simultaneously, a distributed lock (via Redis <code>SETNX</code>) ensures only the first request triggers the AI model, while remaining requests await the populated cache key.</li><li><strong>Eviction Policy</strong>: Least Recently Used (LRU) with memory caps to prioritize viral media while dropping dormant scan records.</li></ul><hr><h2 id="_5-30-second-spoken-interview-answer" tabindex="-1">5. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_5-30-second-spoken-interview-answer" aria-label="Permalink to &quot;5. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;In TruthGuard, caching is implemented across three tiers: TanStack Query in the browser, Cloudflare at the CDN edge, and an Upstash Redis cache keyed by SHA-256 binary hash at the edge gateway.</p><p>By keying our cache directly to the file&#39;s cryptographic hash, duplicate viral deepfakes are resolved in under 5 milliseconds from cache, reducing AI inference bills by over 40% and protecting our models from thundering herd spikes.&quot;</p></blockquote>',9))])}const A=n(u,[["render",g]]);export{v as __pageData,A as default};
